    orgs=[Organisation(id="org-reedwatch",name="Demo Reedwatch Collective",description="Fictional field group contributing demonstration records and coordinating assigned cases.",contact="demo-contact@aquarelay.local",synthetic=True,created_at=date,data={"verification":"Demo identity — no official verification or partnership","responsibility_source":"source-district"}),Organisation(id="org-district",name="Demo District Water Office",description="Fictional case-handling organisation for the demonstration district.",contact="demo-office@aquarelay.local",synthetic=True,created_at=date,data={"verification":"Synthetic organisation — not a public authority"}),Organisation(id="org-research",name="Demo Freshwater Research Circle",description="Fictional research contributors with scoped record-review roles.",contact="demo-research@aquarelay.local",synthetic=True,created_at=date)]
