    fixtures=[("reedwater","Demo Reedwater Lake","lake",77.587,12.979,"Reedwater Quarter","A synthetic lake with community observations, a documented response, and a preserved case history."),("millbank","Demo Millbank Canal","canal",77.594,12.974,"Millbank Ward","A fictional canal with a recorded floating-waste observation under investigation."),("willow","Demo Willow Pond","pond",77.578,12.970,"Willow Gardens","A demonstration pond with biodiversity records. Its environmental condition has not been assessed."),("eastmere","Demo Eastmere Lake","lake",77.609,12.982,"Eastmere Ward","Synthetic monitoring records link a demonstration field dataset to this lake."),("lantern","Demo Lantern Stream","stream",77.600,12.963,"Lantern Walk","A fictional stream with a documented waterway link. Nearby distance alone does not establish a connection."),("orchard","Demo Orchard Pool","pond",77.570,12.981,"Orchard Quarter","A demonstration pond with limited records. Missing observations do not imply safe water."),("northfen","Demo North Fen","wetland",77.599,12.991,"North Fen Ward","A synthetic wetland with coarse biodiversity locations and an outdated source context.")]
