    db.add_all([Case(id="case-historical",waterbody_id="wb-reedwater",organisation_id="org-reedwatch",title="Demo shoreline waste observation",description="Demo scenario: scattered shoreline waste was recorded. A cleanup and follow-up were documented. No ecological recovery conclusion is recorded.",state="closed",review_state="reviewed",observed_at="2026-04-12T07:00:00+00:00",created_at="2026-04-12T08:00:00+00:00",synthetic=True,data={"outcome":"Documented cleanup and follow-up complete; environmental condition not assessed.","completed_at":"2026-05-15T08:00:00+00:00","supporting_record":"action-followup"}),Case(id="case-current",waterbody_id="wb-reedwater",organisation_id="org-reedwatch",title="Demo fish mortality observation",description="Community report of approximately 5–10 fish. This synthetic observation has not yet been reviewed; cause is unknown.",state="new",review_state="unreviewed",observed_at="2026-09-28T04:30:00+00:00",created_at="2026-09-28T05:00:00+00:00",synthetic=True),Case(id="case-millbank",waterbody_id="wb-millbank",organisation_id="org-district",title="Demo floating waste observation",description="Demo inspection records floating waste. An investigation is documented; no environmental cause or safety finding is recorded.",state="investigating",review_state="reviewed",observed_at="2026-09-23T09:00:00+00:00",created_at="2026-09-23T10:00:00+00:00",synthetic=True)])
    db.flush()
