        if kind=="closure": event_data.update(outcome="Documented cleanup and follow-up complete; environmental condition not assessed.",outcome_category="action_documented_completed",completed_at=when,supporting_record="action-followup")
        db.add(Event(id=eid,sequence=int(datetime.fromisoformat(when).timestamp()*1e6)+i,waterbody_id="wb-reedwater",case_id=cid,kind=kind,title=title,description=description,actor_id="user-manager",source_id="source-field",synthetic=True,created_at=when,data=event_data))
