if __name__=="__main__":
    parser=argparse.ArgumentParser(description="Seed AquaRelay synthetic demonstration records. Repeat-safe; no deletion.")
    parser.parse_args()
    if os.getenv("DEMO_MODE","true").lower()!="true":
        print("DEMO_MODE=false: synthetic seed disabled. No data changed.")
    else:
        Base.metadata.create_all(engine)
        with SessionLocal() as db:
            seed(db)
        print("Synthetic district seeded (or already present). No existing records deleted.")


